function LevelGuideDialog:__init()
    self.goodNodes = {}
    self.wayNodes = {}
end

function LevelGuideDialog:__delete()
    self.goodNodes = nil
    self.wayNodes = nil
end

function LevelGuideDialog:Awake()
    UIEventProxy.Create(self.BtnClose.gameObject).onPointerClick = Bind(self, self.OnClickBtnCloseAction)
    UIEventProxy.Create(self.BG.gameObject).onPointerClick = Bind(self, self.OnClickBtnCloseAction)
    UIEventProxy.Create(self.FontStyleButton.gameObject).onPointerClick = Bind(self, self.OnClickReceivedAction)

    self.childCount = self.GoodLayout.transform.childCount
    table.insert(self.wayNodes, self.ElementGroup)

end

function LevelGuideDialog:OnFocus(focus)
    KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, focus)
end

function LevelGuideDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument   = self.controller.Argument
        local parameters = argument.parameters
        local data       = parameters.data
        self.data = data
        self:RefreshUI(data)
    end))
    return coWait
end

function LevelGuideDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

