function LevelGuideDialog:RefreshUI(data)
    local newbieGuideTaskReceived  = data.newbieGuideTaskReceived
    local newbieGuideTaskCurrentId = checkNumber(data.newbieGuideTaskCurrentId)
    --local newbieGuideTaskProgress  = checkNumber(data.newbieGuideTaskProgress)
    local setting = CfUtils.GetCf(AutoIds.IdSetting122, "LevelGuideVo")
    local vos = setting:GetAll()
    local maxTaskId = 0
    for i, v in pairs(vos) do
        maxTaskId = math.max(checkNumber(v.refId), maxTaskId)
    end
    self.maxTaskId = maxTaskId

    ---@type LevelGuideVo
    local levelGuideVo = CfUtils.GetCfVo(AutoIds.IdSetting122, "LevelGuideVo", newbieGuideTaskCurrentId)
    self:RefreshGoodsLayout(levelGuideVo.rewards)

    self:RefreshReceivedState(newbieGuideTaskReceived, newbieGuideTaskCurrentId, levelGuideVo)

    self:RefreshTaskTitleAndContent(levelGuideVo)

    self:RefreshLayoutWays(levelGuideVo)

    self.levelGuideVo = levelGuideVo
end

function LevelGuideDialog:RefreshGoodsLayout(rewards)
    local childCount = self.childCount
    ---@type UnityEngine.RectTransform
    local parent = self.GoodLayout.transform
    local rewardCount = #rewards
    for i = 1, childCount do
        self.goodNodes[i] = self.goodNodes[i] or {}
        local child = self.goodNodes[i].child
        ---@type Engine.UI.ImageAlterable
        local imgComp = self.goodNodes[i].imgComp
        ---@type TMPro.TextMeshProUGUI
        local textComp = self.goodNodes[i].textComp
        if child == nil then
            child = parent:GetChild(i - 1)
            local imgTrans  = child:Find("ImgGoodIcon")
            if imgTrans then
                imgComp = KTool.GetComponent(imgTrans.gameObject, ImageAlterableType)
                self.goodNodes[i].imgComp = imgComp
            end
            local textTrans = child:Find("ImgGoodIcon/Text")
            if textTrans then
                textComp = KTool.GetComponent(textTrans.gameObject, TextMeshProUGUIType)
                self.goodNodes[i].textComp = textComp
            end
        end

        local isShowChild = i <= rewardCount
        KTool.SetActive(child, isShowChild)

        if isShowChild then
            local reward   = rewards[i]
            local photoPath = goodsConfMgr:GetPhotoPathById(reward.goodsId)
            imgComp:LoadSprite(photoPath)

            textComp.text = string.format("x%s", reward.goodsNum)
        end
    end
end

function LevelGuideDialog:RefreshReceivedState(newbieGuideTaskReceived, newbieGuideTaskCurrentId, levelGuideVo)
    --- 1. 检查是否领取过
    local isReceived = false
    for i, id in ipairs(newbieGuideTaskReceived) do
        if checkNumber(id) == newbieGuideTaskCurrentId then
            isReceived = true
            break
        end
    end

    --- 2. 检查是否满足 任务进度
    local isSatisfy = self:CheckIsCompleteProgress(levelGuideVo.taskContentType, levelGuideVo.taskContentId, levelGuideVo.taskContentNum)

    local isCanReceive = not isReceived and isSatisfy
    self.isCanReceive = isCanReceive

    local text = isCanReceive and localize("一键领取") or localize("未达成")
    local styleId = isCanReceive and "B1" or "B16"
    self.FontStyleButton:ResetFontStyle(styleId, text)

    KTool.SetActive(self.ActiveNode.gameObject, isCanReceive)
end

function LevelGuideDialog:RefreshTaskTitleAndContent(levelGuideVo)
    self.TitleText.text = levelGuideVo.title
    self.DescText.text = levelGuideVo.taskDesc
    self.DescTextNumber.text = self:GetDescTextNumberByTaskType(levelGuideVo.taskContentType, levelGuideVo.taskContentId, levelGuideVo.taskContentNum)
end

function LevelGuideDialog:RefreshLayoutWays(levelGuideVo)
    self.TxtWays.text = levelGuideVo.functionDesc

    local childCount = #self.wayNodes
    local functions = levelGuideVo.functionId
    local functionCount = #functions
    local forTimes = math.max(childCount, functionCount)
    local parent = self.LayoutWays.gameObject
    for i = 1, forTimes do
        local child    = self.wayNodes[i]
        local moduleId = functions[i]
        if moduleId then
            if child == nil then
                child = parent:AddChild(self.ElementGroup.gameObject).transform
            end

            local textTrans = child:Find("Text")
            if textTrans then
                local textComp = KTool.GetComponent(textTrans.gameObject, TextType)
                ---@type TableML.TableFileRow
                local row = goodsConfMgr:GetJumpModuleRow(moduleId)
                local functionName = parse_localizeText(row, "functionName", "")
                textComp.text = functionName
            end
            local FontStyleButton = child:Find("FontStyleButton")
            if FontStyleButton then
                UIEventProxy.Create(FontStyleButton.gameObject).onPointerClick = Bind(self, self.OnClickJumpAction)
                ---@type Game.Native.Common.ID
                local idComp = KTool.GetOrAddComponent(FontStyleButton.gameObject, IDType)
                idComp.id = checkNumber(moduleId)
            end

        elseif child then
            KTool.SetActive(self.child.gameObject, false)
        end
    end

end

function LevelGuideDialog:RequestPlayerNewbieGuideTaskDraw()
    local data = self.data
    local newbieGuideTaskCurrentId = checkNumber(data.newbieGuideTaskCurrentId)
    GameUtils.Request(Interfaces.PlayerNewbieGuideTaskDraw, {taskId = newbieGuideTaskCurrentId }, function(_, response)
        if checkNumber(response.errCode) ~= 0 then return end

        local responseData = response.data
        local rewards = responseData.rewards or {}
        GoodsUtils.DrawRewards(rewards)

        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        ---@type PlayerDojo
        local playerDojo = playerComponent.playerDojo
        table.insert(playerDojo.newbieGuideTaskReceived, newbieGuideTaskCurrentId)
        --- newbieGuideTaskCurrentId 只能递加 by chen hong
        playerDojo.newbieGuideTaskCurrentId = newbieGuideTaskCurrentId == self.maxTaskId and 0 or (newbieGuideTaskCurrentId + 1)

        cs_coroutine.start(function()
            cs_coroutine.yield_return(UIModule.BackDialog())
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end)
    end)

end

