function LevelGuideDialog:GetDescTextNumberByTaskType(type, taskContentId, taskContentNum)
    if type == TaskType.QuestType then
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(taskContentId)
        return questVo and questVo.label or ""
    end
    return taskContentNum
end

function LevelGuideDialog:CheckIsCompleteProgress(type, taskContentId, taskContentNum)
    local config = {
        [TaskType.QuestType] = Constants.CommonUnlockType.PassQuest,
        [TaskType.LevelLimit] = Constants.CommonUnlockType.PlayerLevel,
    }
    local targetNumConfig = {
        [TaskType.QuestType] = taskContentId,
        [TaskType.LevelLimit] = taskContentNum,
    }
    local unlockType = config[type]
    if unlockType == nil then
        return false
    end
    return GameUtils.IsUnlockedSingle(unlockType, targetNumConfig[type])
end

