function LevelGuideDialog:OnClickBtnCloseAction()
    UIModule.BackDialog()
end

function LevelGuideDialog:OnClickReceivedAction()
    if not self.isCanReceive then
        return
    end

    self:RequestPlayerNewbieGuideTaskDraw()
end

function LevelGuideDialog:OnClickJumpAction(eventData)
    local gameObject = eventData.pointerCurrentRaycast.gameObject
    local idComp     = gameObject:GetComponent(IDType)
    local moduleId   = idComp.id
    ---@type TableML.TableFileRow
    local row = goodsConfMgr:GetJumpModuleRow(moduleId)
    if row and goodsConfMgr:CheckIsCanJump(row) then
        cs_coroutine.start(function()
            cs_coroutine.yield_return(UIModule.BackDialog())
            goodsConfMgr:ExecuteJump(row, {})
        end)
    end
end

